193				slog.String("url", requestPayload.URL),
194				slog.String("activityType", requestPayload.ActivityType))
195		}
196	}
 25	func (s *APIV1Service) DispatchMemoDeletedWebhook(ctx context.Context, memo *v1pb.Memo) error {
 26		return s.dispatchMemoRelatedWebhook(ctx, memo, "memos.memo.deleted")
 27	}
